export const WEAPON_BY_UNIQUE_ID: ReadonlyMap<number, WeaponDef> = new Map(
  WEAPONS.map((w) => [w.uniqueId, w]),
);

const DEFAULT_WEAPON: WeaponDef = WEAPON_BY_UNIQUE_ID.get(1015) ?? WEAPONS[0];

export function getWeaponDef(uniqueId: number): WeaponDef {
  return WEAPON_BY_UNIQUE_ID.get(uniqueId) ?? DEFAULT_WEAPON;
}

export function getWeaponsByTier(tier: WeaponTier): WeaponDef[] {
  return WEAPONS.filter((w) => w.weaponTier === tier);
}
